// src/components/layout/sidebar.tsx
'use client';

import {
  Home, ShoppingBag, ListOrdered, Heart, Wallet, Settings, LogOut
} from 'lucide-react';
import Link from 'next/link';
import { usePathname } from 'next/navigation'; // <-- 1. Impor hook-nya

const menuItems = [
  { icon: Home, text: 'Home', href: '/' },
  { icon: ShoppingBag, text: 'Products', href: '/products' }, // Beri path unik untuk contoh
  { icon: ListOrdered, text: 'Order List', href: '/orders' }, // Beri path unik untuk contoh
  { icon: Heart, text: 'Favorite', href: '/favorites' },
  { icon: Wallet, text: 'Payment', href: '/payment' },
  { icon: Settings, text: 'Settings', href: '/settings' },
];

const Sidebar = () => {
  const pathname = usePathname(); // <-- 2. Panggil hook-nya untuk mendapatkan path saat ini

  return (
    <aside className="w-64 bg-white p-6 flex flex-col justify-between">
      <div>
        <h1 className="text-2xl font-bold mb-10 ml-4">N</h1>
        <nav>
          <ul>
            {menuItems.map((item, index) => {
              // 3. Cek apakah path saat ini sama dengan href dari menu item
              const isActive = pathname === item.href;

              return (
                <li key={index}>
                  <Link 
                     href={item.href} 
                     className={`flex items-center py-3 px-4 my-1 rounded-lg transition-colors
                     ${
                       isActive 
                         ? 'bg-brand-primary text-black font-semibold' // Gaya untuk menu aktif
                         : 'text-brand-text-secondary hover:bg-gray-100' // Gaya untuk menu non-aktif
                     }`}
                  >
                    <item.icon className="w-5 h-5 mr-3" />
                    {item.text}
                  </Link>
                </li>
              );
            })}
          </ul>
        </nav>
      </div>
      <div>
         <Link href="#" className="flex items-center py-3 px-4 rounded-lg text-brand-text-secondary hover:bg-gray-100">
            <LogOut className="w-5 h-5 mr-3" />
            Log Out
         </Link>
      </div>
    </aside>
  );
};

export default Sidebar;